"""File to house all functions related to interfacing with the Calculations Properties dialog of the Monaco Application"""

from .objects.monaco_calculation_properties_objects import MonacoCalcPropertiesObjects
from interops.libraries.squish_actions import CommonActions
from interops.libraries.squish_actions.exceptions import FailedToFindObject
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MONACO_APP_NAME

@deco.set_separate_app_context(MONACO_APP_NAME)
def set_grid_spacing_value(spacingValue: float) -> None:
    """Locates the Calculation Properties Dialog and clears any value inside the Grid Spacing text box >
    then enters the given spacingValue float value into the textbox.

    :param spacingValue: Float value for the grid spacing value to be entered.
    :type spacingValue: float
    :raises FailedToFindObject: Raises when the Calculation Properties Dialog is not visable and enabled.
    """
    if CommonActions.find_object(MonacoCalcPropertiesObjects.calculation_Properties_Dialog) is None:
        raise FailedToFindObject("Object Not Found: Could not find the Calculation Properies Dialog.")
    CommonActions.double_click_object(MonacoCalcPropertiesObjects.calculation_Properties_Grid_Spacing_Edit)
    CommonActions.press_key_sequence_ctrl_a()
    CommonActions.press_delete_key()
    CommonActions.type_in_textfield(MonacoCalcPropertiesObjects.calculation_Properties_Grid_Spacing_Edit, str(spacingValue))

@deco.set_separate_app_context(MONACO_APP_NAME)
def click_calculation_properties_ok_button() -> None:
    """Locates the Calculation Properties Dialog and then left mouse clicks the OK button.

    Waits for Calculation Properties Dialog to disappear.

    :raises FailedToFindObject: Raises when the Calculation Properties Dialog is not visable and enabled.
    """
    if CommonActions.find_object(MonacoCalcPropertiesObjects.calculation_Properties_Dialog) is None:
        raise FailedToFindObject("Object Not Found: Could not find the Calculation Properies Dialog.")
    CommonActions.left_click_object(MonacoCalcPropertiesObjects.calculation_Properties_OK_Button)
    CommonActions.wait_for_object_to_disappear(MonacoCalcPropertiesObjects.calculation_Properties_Dialog)